// www.javidtrading.com — Workers + static assets (./public, generated by `node src/build.mjs`).
//
// Static pages are served by the assets layer before this code runs (no run_worker_first), so
// this worker only sees /api/* and paths that have no file (legacy hub URLs, 404s).
//
//   /api/live-capture*   hourly dashboard captures (R2 bucket LIVE_CAPTURES, secret LIVE_CAPTURE_KEY)
//   /api/v1/*            read-only public data API
//   /api/board/*         community board (D1 BOARD_DB = javid-board-db-bitget, shared with bg's API;
//                        admin actions need BOARD_ADMIN_KEY, which is deliberately NOT set here —
//                        replies/deletes keep going through bg.javidtrading.com/api/board as before)
//   downloads            are NOT served here: buttons link to each exchange worker's /api/download,
//                        which counts the download in that exchange's D1 with landing attribution.
import { upload, latest, image } from "./functions/api/live_capture.js";
import { v1 } from "./functions/api/v1.js";
import { onRequestGet as boardListGet, onRequestPost as boardListPost } from "./functions/api/board/posts.js";
import { onRequestGet as boardItemGet } from "./functions/api/board/posts/[id].js";

const LANGS = ["ko", "ja", "es", "fr", "vi", "tr", "pt"];

function redirect(url, to, status = 301) {
  const target = new URL(to, url.origin);
  // keep campaign tags etc.; never carry "lang" (it becomes the path)
  for (const [k, v] of url.searchParams) if (k !== "lang" && !target.searchParams.has(k)) target.searchParams.set(k, v);
  return Response.redirect(target.toString(), status);
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const { pathname } = url;
    const base = { request, env, ctx, params: {} };
    try {
      if (pathname === "/api/live-capture") {
        if (request.method === "POST") return await upload(base);
        return new Response("method not allowed", { status: 405, headers: { Allow: "POST" } });
      }
      if (pathname === "/api/live-capture/latest") return await latest(base);
      if (pathname.startsWith("/api/live-capture/img/")) {
        base.params = { path: decodeURIComponent(pathname.slice("/api/live-capture/img/".length)) };
        return await image(base);
      }
      if (pathname.startsWith("/api/v1/")) return await v1(request, env, pathname);
      if (pathname === "/api/board/posts") {
        if (request.method === "GET") return await boardListGet(base);
        if (request.method === "POST") return await boardListPost(base);
      }
      const pm = pathname.match(/^\/api\/board\/posts\/(\d+)$/);
      if (pm && request.method === "GET") { base.params = { id: pm[1] }; return await boardItemGet(base); }
      if (pathname.startsWith("/api/")) {
        return new Response(JSON.stringify({ error: "not_found" }), { status: 404, headers: { "Content-Type": "application/json" } });
      }
    } catch (err) {
      return new Response(JSON.stringify({ error: "server_error" }), { status: 500, headers: { "Content-Type": "application/json" } });
    }

    // legacy hub URLs (the old splitter site) -> new pages
    if (pathname === "/install-help" || pathname === "/install-help.html") {
      const l = url.searchParams.get("lang");
      return redirect(url, (LANGS.includes(l) ? `/${l}/download` : "/download") + "#install");
    }
    if (pathname === "/index.html") return redirect(url, "/");

    return env.ASSETS.fetch(request);
  },
};
